package com.mediconnect.clinicalnote.api;
import java.util.*; import com.mediconnect.clinicalnote.application.ClinicalNoteService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") @Tag(name="Clinical Notes") @SecurityRequirement(name="bearerAuth") public class ClinicalNoteController { private final ClinicalNoteService service; public ClinicalNoteController(ClinicalNoteService service){this.service=service;} @PostMapping("/appointments/{appointmentId}/clinical-notes") @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Write clinical evolution note",description="DOCTOR-only. The authenticated doctor must be assigned to the referenced appointment.") public ClinicalNoteResponse create(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID appointmentId,@Valid @RequestBody ClinicalNoteRequest request){return service.createForAssignedAppointment(jwt.getSubject(),appointmentId,request);} @GetMapping("/clinical-notes/me") @Operation(summary="Read my clinical evolution history",description="PATIENT-only. MongoDB results are filtered by the authenticated patient's own ID.") public List<ClinicalNoteResponse> mine(@AuthenticationPrincipal Jwt jwt){return service.listForPatient(jwt.getSubject());} }
